new='''    void recordLifoSignal(int rankPermille) {\n        const bool nearNewest = rankPermille <= kLifoRankThresholdPermille;\n        recentRemovalRanks.push_back(nearNewest ? 1 : 0);\n        if (nearNewest) ++nearNewestRemovalCount;\n        if (recentRemovalRanks.size() > kLifoRankWindow) {\n            nearNewestRemovalCount -= static_cast<std::size_t>(recentRemovalRanks.front());\n            recentRemovalRanks.pop_front();\n        }\n        refreshLifoMode();\n    }\n\n    void recordCommandKind(bool placement) {\n        recentCommandKinds.push_back(placement ? 1 : 0);\n        if (placement) ++recentCommandAdds;\n        else ++recentCommandRemoves;\n        if (recentCommandKinds.size() > kLifoEventWindow) {\n            if (recentCommandKinds.front() != 0) --recentCommandAdds;\n            else --recentCommandRemoves;\n            recentCommandKinds.pop_front();\n        }\n        refreshLifoMode();\n    }\n\n    void refreshLifoMode() {\n        if (recentCommandKinds.size() < kLifoEventWindow ||\n            recentRemovalRanks.size() < kLifoMinObservations) return;\n        const std::size_t n = recentCommandKinds.size();\n        const bool balancedChurn =\n            recentCommandAdds * 100 >= n * static_cast<std::size_t>(kLifoMinEventFractionPercent) &&\n            recentCommandRemoves * 100 >= n * static_cast<std::size_t>(kLifoMinEventFractionPercent) &&\n            std::max(recentCommandAdds, recentCommandRemoves) -\n                std::min(recentCommandAdds, recentCommandRemoves) <=\n                std::max<std::size_t>(16, activePipeCount *\n                    static_cast<std::size_t>(kLifoMaxNetChangePercent) / 100);\n        const std::size_t rankN = recentRemovalRanks.size();\n        const int requiredPercent = lifoTailMode ? kLifoDisablePercent : kLifoEnablePercent;\n        const bool rankSignal = nearNewestRemovalCount * 100 >=\n            rankN * static_cast<std::size_t>(requiredPercent);\n        if (!lifoTailMode && balancedChurn && rankSignal) {\n            lifoTailMode = true;\n            const StartIter tail = tailGap();\n            lifoArenaStart = tail == freeByStart.end() ? trenchLength : tail->first;\n        } else if (lifoTailMode && (!balancedChurn || !rankSignal)) {\n            lifoTailMode = false;\n        }\n    }'''
